BEGIN;SET LOCAL statement_timeout='10s';SET LOCAL lock_timeout='1s';WITH picked AS (SELECT ctid FROM public.lead_commercial WHERE commercial_stage='aguardando_resposta' AND response_deadline_at IS NULL ORDER BY leads_id LIMIT 500 FOR UPDATE SKIP LOCKED),updated AS (UPDATE public.lead_commercial lc SET awaiting_response_since=coalesce(lc.awaiting_response_since,lc.lead_commercial_updated_at,now()),response_deadline_at=coalesce(lc.response_deadline_at,coalesce(lc.lead_commercial_updated_at,now())+interval '72 hours') FROM picked p WHERE lc.ctid=p.ctid RETURNING 1) SELECT (SELECT count(*) FROM updated) AS updated,(SELECT count(*) FROM public.lead_commercial WHERE commercial_stage='aguardando_resposta' AND response_deadline_at IS NULL) AS remaining;COMMIT;-- Repita até remaining=0.
